<?php $pageTitle='Record Cleaning';require 'includes/header.php';$traps=$pdo->query("SELECT id,trap_code,location FROM grease_traps ORDER BY trap_code")->fetchAll();$errors=[];$v=['grease_trap_id'=>'','cleaning_date'=>date('Y-m-d'),'cleaned_by'=>'GreenLeaf Maintenance Team','remarks'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){$v['grease_trap_id']=$_POST['grease_trap_id']??'';$v['cleaning_date']=$_POST['cleaning_date']??'';$v['cleaned_by']=trim($_POST['cleaned_by']??'');$v['remarks']=trim($_POST['remarks']??'');if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))$errors[]='Invalid form submission.';if(!filter_var($v['grease_trap_id'],FILTER_VALIDATE_INT))$errors[]='Select a grease trap.';if($v['cleaning_date']==='')$errors[]='Cleaning date is required.';if($v['cleaned_by']==='')$errors[]='Cleaned by is required.';
if(!$errors){$q=$pdo->prepare("SELECT id FROM grease_traps WHERE id=?");$q->execute([(int)$v['grease_trap_id']]);if(!$q->fetchColumn())$errors[]='Selected trap does not exist.';}
if(!$errors){try{$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO cleaning_records(grease_trap_id,cleaning_date,cleaned_by,remarks) VALUES(?,?,?,?)");$q->execute([(int)$v['grease_trap_id'],$v['cleaning_date'],$v['cleaned_by'],$v['remarks']?:null]);$q=$pdo->prepare("UPDATE grease_traps SET last_cleaned_date=? WHERE id=?");$q->execute([$v['cleaning_date'],(int)$v['grease_trap_id']]);$pdo->commit();flash('success','Cleaning record added and schedule updated.');header('Location: cleaning_records.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Unable to save the cleaning record.';}}}?>
<section class="form-panel"><h3>Record Cleaning</h3><p>Record a completed grease trap cleaning.</p><?php if($errors):?><div class="errors"><?php foreach($errors as $e):?><div><?=h($e)?></div><?php endforeach;?></div><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><label>Grease Trap<select name="grease_trap_id" required><option value="">Select a trap</option><?php foreach($traps as $t):?><option value="<?=$t['id']?>" <?=$v['grease_trap_id']==$t['id']?'selected':''?>><?=h($t['trap_code'].' — '.$t['location'])?></option><?php endforeach;?></select></label><label>Cleaning Date<input type="date" name="cleaning_date" required value="<?=h($v['cleaning_date'])?>"></label><label>Cleaned By<input name="cleaned_by" required value="<?=h($v['cleaned_by'])?>"></label><label>Remarks<input name="remarks" maxlength="255" value="<?=h($v['remarks'])?>"></label><div class="actions"><a class="btn secondary" href="cleaning_records.php">Cancel</a><button class="btn primary">Save Cleaning Record</button></div></form></section><?php require 'includes/footer.php';?>